"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[57114],{3331:(e,t,s)=>{s.d(t,{R:()=>a,x:()=>o});var i=s(36672);const n={},r=i.createContext(n);function a(e){const t=i.useContext(r);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:a(e.components),i.createElement(r.Provider,{value:t},e.children)}},69445:(e,t,s)=>{s.r(t),s.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>a,metadata:()=>i,toc:()=>u});const i=JSON.parse('{"id":"2023/03/31","title":"31","description":"March 31, 2023","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/2023/03/31.md","sourceDirName":"2023/03","slug":"/2023/03/31","permalink":"/fr/2023/03/31","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/fr/docusaurus-plugin-content-docs//current/2023/03/31.md","tags":[],"version":"current","frontMatter":{"localized_date":"31 mars 2023","top_news":"Le projet de loi am\xe9ricain sur l\'interdiction soul\xe8ve des inqui\xe9tudes pour les VPN et TikTok"},"sidebar":"defaultSidebar","previous":{"title":"01","permalink":"/fr/2023/04/01"},"next":{"title":"2023-03-30","permalink":"/fr/2023/03/30"}}');var n=s(23420),r=s(3331);const a={localized_date:"31 mars 2023",top_news:"Le projet de loi am\xe9ricain sur l'interdiction soul\xe8ve des inqui\xe9tudes pour les VPN et TikTok"},o=void 0,l={},u=[{value:"March 31, 2023",id:"march-31-2023",level:2},{value:"Le projet de loi am\xe9ricain sur l&#39;interdiction soul\xe8ve des inqui\xe9tudes pour les VPN et TikTok",id:"le-projet-de-loi-am\xe9ricain-sur-linterdiction-soul\xe8ve-des-inqui\xe9tudes-pour-les-vpn-et-tiktok",level:2},{value:"Des opinions mitig\xe9es sur la valeur de Y Combinator pour les startups",id:"des-opinions-mitig\xe9es-sur-la-valeur-de-y-combinator-pour-les-startups",level:2},{value:"Scratch : Langage de programmation visuel populaire pour les enfants",id:"scratch--langage-de-programmation-visuel-populaire-pour-les-enfants",level:2},{value:"D\xe9fis et compromis dans la technologie de l&#39;\xe9clairage LED",id:"d\xe9fis-et-compromis-dans-la-technologie-de-l\xe9clairage-led",level:2},{value:"Plus de la moiti\xe9 des nouveaux paquets NPM sont des spams",id:"plus-de-la-moiti\xe9-des-nouveaux-paquets-npm-sont-des-spams",level:2},{value:"Les \xc9tats-Unis proposent des projets de loi qui menacent la libert\xe9 technologique et la protection de la vie priv\xe9e",id:"les-\xe9tats-unis-proposent-des-projets-de-loi-qui-menacent-la-libert\xe9-technologique-et-la-protection-de-la-vie-priv\xe9e",level:2},{value:"Moteur de rendu 3D open-source pour l&#39;\xe9ducation et l&#39;int\xe9gration",id:"moteur-de-rendu-3d-open-source-pour-l\xe9ducation-et-lint\xe9gration",level:2},{value:"Google nie avoir utilis\xe9 le ChatGPT d&#39;OpenAI pour entra\xeener Bard",id:"google-nie-avoir-utilis\xe9-le-chatgpt-dopenai-pour-entra\xeener-bard",level:2},{value:"L&#39;API de Twitter n\xe9glig\xe9e, le m\xe9contentement des utilisateurs s&#39;accro\xeet",id:"lapi-de-twitter-n\xe9glig\xe9e-le-m\xe9contentement-des-utilisateurs-saccro\xeet",level:2},{value:"Le directeur du syndicat de police de San Jose accus\xe9 de trafic de drogue",id:"le-directeur-du-syndicat-de-police-de-san-jose-accus\xe9-de-trafic-de-drogue",level:2}];function d(e){const t={a:"a",h2:"h2",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h2,{id:"march-31-2023",children:"March 31, 2023"}),"\n",(0,n.jsx)(t.h2,{id:"le-projet-de-loi-am\xe9ricain-sur-linterdiction-soul\xe8ve-des-inqui\xe9tudes-pour-les-vpn-et-tiktok",children:"Le projet de loi am\xe9ricain sur l'interdiction soul\xe8ve des inqui\xe9tudes pour les VPN et TikTok"}),"\n",(0,n.jsxs)(t.p,{children:["Un projet de loi d'interdiction am\xe9ricain soutenu par la Maison Blanche et visant \xe0 r\xe9guler l'internet pourrait rendre les VPN ill\xe9gaux, entra\xeener des amendes allant jusqu'\xe0 1 million de dollars et 20 ans d'emprisonnement, et \xeatre consid\xe9r\xe9 comme une attaque contre les libert\xe9s civiles. Le projet de loi b\xe9n\xe9ficie d'un soutien bipartisan et se concentre sur les questions de s\xe9curit\xe9 nationale li\xe9es \xe0 la Chine et sur la limitation des relations commerciales avec ce pays. L'UE pourrait ne pas suivre la tendance am\xe9ricaine, car les pays ont leur propre structure juridique, et l'interdiction de TikTok pourrait susciter le ressentiment des jeunes et des repr\xe9sailles contre le gouvernement am\xe9ricain. Les d\xe9tracteurs de l'interdiction affirment qu'elle menace la vie priv\xe9e et la libert\xe9 de parole et d'expression.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35366955",children:"Hacker News Link"}),", ",(0,n.jsx)(t.a,{href:"https://www.youtube.com/watch?v=FWQGA_n5Z4M",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"des-opinions-mitig\xe9es-sur-la-valeur-de-y-combinator-pour-les-startups",children:"Des opinions mitig\xe9es sur la valeur de Y Combinator pour les startups"}),"\n",(0,n.jsxs)(t.p,{children:["Les avis sur la valeur de Y Combinator (YC) pour les startups sont mitig\xe9s, en fonction des perspectives et des besoins de chacun. Si certains appr\xe9cient le r\xe9seau et le mentorat de YC, d'autres critiquent ses conseils et sa focalisation sur les objectifs \xe0 court terme. La r\xe9putation et la marque de YC peuvent aider \xe0 la collecte de fonds, mais son accord SAFE non plafonn\xe9 et l'accent mis sur la croissance \xe0 tout prix peuvent ne pas convenir \xe0 tous les fondateurs. L'importance de la cr\xe9ation d'une communaut\xe9 et des relations personnelles dans le cadre d'un format \xe0 distance seulement est \xe9galement d\xe9battue. En fin de compte, la valeur de YC d\xe9pend de la capacit\xe9 d'un fondateur \xe0 utiliser ses ressources pour maximiser ses chances de r\xe9ussite.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35373019",children:"Lien Hacker News"}),", ",(0,n.jsx)(t.a,{href:"https://acecreamu.substack.com/p/is-y-combinator-worth-the-money",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"scratch--langage-de-programmation-visuel-populaire-pour-les-enfants",children:"Scratch : Langage de programmation visuel populaire pour les enfants"}),"\n",(0,n.jsxs)(t.p,{children:["Scratch est un langage de programmation visuel populaire destin\xe9 aux enfants, qui utilise des blocs color\xe9s au lieu d'un codage textuel pour les aider \xe0 apprendre les concepts de programmation. Le programme comprend des principes de programmation de base tels que les variables, les listes, les structures de flux de contr\xf4le if/else et en boucle, ainsi que la concurrence bas\xe9e sur les \xe9v\xe9nements. Scratch a une approche simple et conviviale pour encourager les enfants \xe0 explorer le calcul de mani\xe8re cr\xe9ative, et met fortement l'accent sur l'interaction avec les pairs et le partage du travail pour recevoir un retour d'information. La communaut\xe9 Scratch est l'une des plus grandes communaut\xe9s de codage au monde, avec plus de 103 millions d'utilisateurs et 123 millions de projets partag\xe9s sur la plateforme. Bien que les r\xe9seaux sociaux non r\xe9glement\xe9s et les enfants qui jouent \xe0 des jeux vid\xe9o au lieu d'utiliser Scratch \xe0 des fins \xe9ducatives suscitent des inqui\xe9tudes, l'outil a incit\xe9 de nombreuses personnes \xe0 s'int\xe9resser \xe0 la programmation, avec des projets allant de l'initiation au codage \xe0 des comp\xe9tences de programmation avanc\xe9es.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35373052",children:"Lien Hacker News"}),", ",(0,n.jsx)(t.a,{href:"https://scratch.mit.edu/about",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"d\xe9fis-et-compromis-dans-la-technologie-de-l\xe9clairage-led",children:"D\xe9fis et compromis dans la technologie de l'\xe9clairage LED"}),"\n",(0,n.jsxs)(t.p,{children:["Les ampoules LED sont confront\xe9es \xe0 des probl\xe8mes de d\xe9faillance rapide, de mauvais rendu des couleurs et d'indices de similarit\xe9 spectrale, d'alimentation \xe9lectrique mal con\xe7ue, de surchauffe et de co\xfbt plus \xe9lev\xe9 pour l'\xe9clairage int\xe9rieur. Les alimentations \xe0 courant constant sont n\xe9cessaires pour l'\xe9clairage \xe0 LED, et les luminaires doivent \xeatre con\xe7us diff\xe9remment des ampoules \xe0 incandescence pour dissiper la chaleur. La fiabilit\xe9 et la durabilit\xe9 des ampoules LED suscitent des inqui\xe9tudes, bien que des options de haute qualit\xe9 soient disponibles \xe0 un prix plus \xe9lev\xe9. L'int\xe9gration des ampoules LED dans les variateurs de lumi\xe8re et la garantie de leur compatibilit\xe9 posent des probl\xe8mes. Le scintillement et le manque de vivacit\xe9 de l'\xe9clairage LED ont conduit au d\xe9veloppement de nouveaux syst\xe8mes de classification et d'ampoules LED r\xe9glables. Dans l'ensemble, la technologie LED a du potentiel mais n\xe9cessite un d\xe9veloppement et une innovation continus.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35371750",children:"Lien Hacker News"}),", ",(0,n.jsx)(t.a,{href:"https://nymag.com/strategist/article/led-light-bulbs-investigation.html",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"plus-de-la-moiti\xe9-des-nouveaux-paquets-npm-sont-des-spams",children:"Plus de la moiti\xe9 des nouveaux paquets NPM sont des spams"}),"\n",(0,n.jsxs)(t.p,{children:["Plus de la moiti\xe9 des nouveaux paquets npm soumis sont des spams, dont beaucoup contiennent des liens vers des sites web malveillants ou offrent de faux cadeaux comme les V-Bucks de Fortnite. L'augmentation du spam serait li\xe9e aux camps d'entra\xeenement au codage, o\xf9 les \xe9tudiants sont encourag\xe9s \xe0 publier des paquets m\xeame s'ils ne font rien. Les personnes interrog\xe9es ont propos\xe9 des solutions telles que des processus de test automatis\xe9s et un mod\xe8le de confiance sur le web. Cette question met en \xe9vidence la nature complexe de l'\xe9thique dans le secteur du d\xe9veloppement de logiciels et les tensions entre la libert\xe9 d'expression et les droits de propri\xe9t\xe9 priv\xe9e. Des chercheurs en s\xe9curit\xe9 ont identifi\xe9 la pr\xe9sence de paquets de spam dans l'ensemble du registre npm et m\xe8nent actuellement une enqu\xeate plus approfondie.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35370728",children:"Lien Hacker News"}),", ",(0,n.jsx)(t.a,{href:"https://blog.sandworm.dev/one-in-two-new-npm-packages-is-seo-spam-right-now",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"les-\xe9tats-unis-proposent-des-projets-de-loi-qui-menacent-la-libert\xe9-technologique-et-la-protection-de-la-vie-priv\xe9e",children:"Les \xc9tats-Unis proposent des projets de loi qui menacent la libert\xe9 technologique et la protection de la vie priv\xe9e"}),"\n",(0,n.jsxs)(t.p,{children:["Le gouvernement am\xe9ricain a propos\xe9 un projet de loi qui donnerait un pouvoir sans pr\xe9c\xe9dent pour interdire toute technologie \xe9trang\xe8re qu'il consid\xe8re comme une \"menace pour la s\xe9curit\xe9 nationale\", ce qui fait dire \xe0 certains qu'il pourrait conduire \xe0 des pouvoirs de censure similaires \xe0 ceux de la Chine et qu'il serait beaucoup plus large que ce que l'on pensait au d\xe9part. L'interdiction des applications de m\xe9dias sociaux appartenant \xe0 des Chinois fait \xe9galement l'objet d'un d\xe9bat, certains estimant qu'il s'agit d'une pente glissante vers la censure de l'information, tandis que d'autres soutiennent qu'elle est n\xe9cessaire pour emp\xeacher les entreprises chinoises de voler la technologie am\xe9ricaine et de recueillir des informations \xe0 des fins d'espionnage. La loi RESTRICT est une proposition de loi qui pourrait \xeatre utilis\xe9e pour interdire TikTok et les VPN, et ses d\xe9tracteurs affirment qu'elle pourrait violer le premier amendement. Des s\xe9nateurs r\xe9publicains ont \xe9galement propos\xe9 d'interdire aux employ\xe9s f\xe9d\xe9raux d'utiliser des applications de m\xe9dias sociaux appartenant \xe0 des entreprises chinoises, en raison de pr\xe9occupations li\xe9es \xe0 l'espionnage et \xe0 la surveillance. Certains commentateurs estiment que cette l\xe9gislation rel\xe8ve du protectionnisme gouvernemental, tandis que d'autres affirment que la croissance des m\xe9dias sociaux nuit \xe0 la sant\xe9 mentale et contribue \xe0 la manipulation de l'opinion publique.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35369075",children:"Hacker News Link"}),", ",(0,n.jsx)(t.a,{href:"https://www.vice.com/en/article/4a3ddb/restrict-act-insanely-broad-ban-tiktok-vpns",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"moteur-de-rendu-3d-open-source-pour-l\xe9ducation-et-lint\xe9gration",children:"Moteur de rendu 3D open-source pour l'\xe9ducation et l'int\xe9gration"}),"\n",(0,n.jsxs)(t.p,{children:["Un d\xe9veloppeur a publi\xe9 le moteur de rendu 3D open-source StratusGFX afin que les utilisateurs puissent int\xe9grer son code de rendu dans d'autres moteurs ou l'utiliser comme ressource \xe9ducative. Ses capacit\xe9s comprennent les r\xe9flexions en temps r\xe9el, les ombres et la prise en charge compl\xe8te de l'ombrage PBR, mais il n'est actuellement compatible qu'avec OpenGL. Son cr\xe9ateur envisage de porter le moteur de rendu sur Vulkan afin d'am\xe9liorer la compatibilit\xe9 multiplateforme. Le moteur StratusGFX est con\xe7u pour maximiser le r\xe9alisme, mais avec des capacit\xe9s de compromis de repli pour le mat\xe9riel moins puissant, et son architecture est disponible sur Github pour Windows et Linux. Le moteur est en pr\xe9version/b\xeataversion, et il faut s'attendre \xe0 des bogues et \xe0 une instabilit\xe9 importants.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35370284",children:"Lien Hacker News"}),", ",(0,n.jsx)(t.a,{href:"https://github.com/KTStephano/StratusGFX",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"google-nie-avoir-utilis\xe9-le-chatgpt-dopenai-pour-entra\xeener-bard",children:"Google nie avoir utilis\xe9 le ChatGPT d'OpenAI pour entra\xeener Bard"}),"\n",(0,n.jsxs)(t.p,{children:["Google nie avoir utilis\xe9 le ChatGPT d'OpenAI pour entra\xeener Bard, un nouveau mod\xe8le de langage. Des inqui\xe9tudes ont \xe9t\xe9 soulev\xe9es quant \xe0 l'\xe9thique de l'entra\xeenement d'un grand mod\xe8le de langage avec les r\xe9sultats d'un autre mod\xe8le de langage contr\xf4l\xe9 commercialement. Les conditions d'utilisation d'OpenAI interdisent d'entra\xeener des mod\xe8les concurrents \xe0 l'aide de ses r\xe9sultats de ML, mais Google n'est pas tenu de respecter cette r\xe8gle. Un ancien employ\xe9 de Google a affirm\xe9 avoir utilis\xe9 des donn\xe9es de l'OpenAI, ce que Google d\xe9ment. Le mat\xe9riel g\xe9n\xe9r\xe9 par l'IA n'est pas soumis au droit d'auteur, et l'entra\xeenement sur d'autres mod\xe8les est autoris\xe9. Certains affirment que le vol de ChatGPT pourrait \xeatre moralement justifi\xe9 puisqu'il s'agit d'une source collective, mais que l'entra\xeenement de mod\xe8les sur d'autres donn\xe9es g\xe9n\xe9r\xe9es par l'IA pourrait constituer une mauvaise donn\xe9e.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35370915",children:"Lien Hacker News"}),", ",(0,n.jsx)(t.a,{href:"https://twitter.com/steventey/status/1641267979399704576",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"lapi-de-twitter-n\xe9glig\xe9e-le-m\xe9contentement-des-utilisateurs-saccro\xeet",children:"L'API de Twitter n\xe9glig\xe9e, le m\xe9contentement des utilisateurs s'accro\xeet"}),"\n",(0,n.jsxs)(t.p,{children:["L'API de Twitter ne serait pas entretenue, ce qui entra\xeenerait des probl\xe8mes d'instabilit\xe9 pour les utilisateurs. Certains utilisateurs ont d\xe9clar\xe9 se sentir \xe9trangers au service en raison de la diminution du contenu des articles scientifiques et de l'augmentation de la proportion de contenu incendiaire ou offensant. De nombreuses plateformes de m\xe9dias sociaux utilisent des flux algorithmiques, mais les param\xe8tres par d\xe9faut sont importants car ils influencent le comportement des utilisateurs. Les utilisateurs de Twitter rencontrent des probl\xe8mes tels que des erreurs de serveur interne et des difficult\xe9s d'acc\xe8s au site web, ce qui a conduit certains d'entre eux \xe0 passer \xe0 des plateformes alternatives telles que Mastodon. Les r\xe9cents probl\xe8mes d'instabilit\xe9 de Twitter ont pouss\xe9 certains utilisateurs \xe0 r\xe9duire leur utilisation. Malgr\xe9 ces inqui\xe9tudes, certains pensent que la croissance de Twitter sous la direction de Musk sugg\xe8re que la plateforme continuera \xe0 prosp\xe9rer, avec ou sans ses utilisateurs d\xe9vou\xe9s. La d\xe9cision d'Elon Musk de restreindre l'acc\xe8s \xe0 l'API de Twitter suscite la controverse, ses d\xe9tracteurs l'accusant de conduire intentionnellement Twitter \xe0 la faillite. L'API de Twitter n'est effectivement plus maintenue, un seul employ\xe9 postant r\xe9guli\xe8rement sur le forum Twitter Developers et se concentrant uniquement sur l'API Ads.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35370152",children:"Lien Hacker News"}),", ",(0,n.jsx)(t.a,{href:"https://snarfed.org/the-twitter-api-is-now-effectively-unmaintained",children:"Original Post"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"le-directeur-du-syndicat-de-police-de-san-jose-accus\xe9-de-trafic-de-drogue",children:"Le directeur du syndicat de police de San Jose accus\xe9 de trafic de drogue"}),"\n",(0,n.jsxs)(t.p,{children:["La directrice ex\xe9cutive de l'Association des officiers de police de San Jose, Sonia Rosa Segovia, a \xe9t\xe9 accus\xe9e d'avoir introduit du fentanyl en contrebande aux \xc9tats-Unis et d'avoir g\xe9r\xe9 un commerce de drogue en partie \xe0 partir de son bureau. Segovia aurait utilis\xe9 l'adresse de l'association pour envoyer des colis \xe0 des clients et aurait discut\xe9 des affaires de la police avec ses fournisseurs. Au moins un de ses clients est mort d'une overdose et elle doit r\xe9pondre de plusieurs chefs d'accusation li\xe9s \xe0 la drogue. D'autres cas de policiers impliqu\xe9s dans le trafic de drogue ont soulev\xe9 des questions sur le r\xf4le des forces de l'ordre dans le commerce ill\xe9gal de la drogue, certains sugg\xe9rant la l\xe9galisation comme solution. Le d\xe9bat sur la l\xe9galisation des drogues porte \xe9galement sur les externalit\xe9s et la n\xe9cessit\xe9 de mettre en place des syst\xe8mes de soutien. Joanne Southerland, directrice ex\xe9cutive du syndicat de la police de San Jose, a \xe9galement \xe9t\xe9 accus\xe9e de trafic de drogue, de m\xeame que Joanne Segovia, employ\xe9e du syndicat de la police, qui a \xe9t\xe9 inculp\xe9e pour avoir import\xe9 de la m\xe9thamph\xe9tamine aux \xc9tats-Unis. Ces affaires soulignent la n\xe9cessit\xe9 de trouver des solutions pour lutter contre le trafic de drogue et la toxicomanie, notamment par des changements culturels et des efforts cibl\xe9s en mati\xe8re de r\xe9pression.\n",(0,n.jsx)(t.a,{href:"http://news.ycombinator.com/item?id=35376488",children:"Hacker News Link"}),", ",(0,n.jsx)(t.a,{href:"https://www.washingtonexaminer.com/news/crime/san-jose-police-union-director-smuggle-fentanyl-charge",children:"Original Post"}),"."]})]})}function c(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}}}]);